{"content":"import React from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import { loadFont as loadSans } from "@remotion/google-fonts/InterTight";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";

/* Twinthos · 15-second showreel. Why → product → benefits → promise.
   Tokens mirror the live twinthos.com dark surfaces. */
const sans = loadSans("normal", { weights: ["400", "500", "600"], subsets: ["latin"], ignoreTooManyRequestsWarning: true });
const mono = loadMono("normal", { weights: ["400"], subsets: ["latin"], ignoreTooManyRequestsWarning: true });

const C = {
  bg: "#0E100E", ink: "#F4F0E6", ink2: "#CAC6BA", mute: "rgba(244,240,230,.46)",
  line: "rgba(244,240,230,.16)", green: "#6CC79A", amber: "#E6A54D",
  sans: `${sans.fontFamily}, sans-serif`, mono: `${mono.fontFamily}, monospace`,
};
const E = Easing.bezier(0.2, 0.7, 0.1, 1);
const EIO = Easing.bezier(0.65, 0, 0.25, 1);
const ip = (t: number, a: number, b: number, c: number, d: number, e = E) =>
  interpolate(t, [a, b], [c, d], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: e });
const win = (t: number, a: number, b: number, fi = 0.35, fo = 0.3) =>
  Math.min(ip(t, a, a + fi, 0, 1), 1 - ip(t, b - fo, b, 0, 1));

const MarkPath = "M11 12H30.75V52H26V20H11ZM33.25 12H53V20H38V52H33.25Z";
const Mark: React.FC<{ size: number; color?: string }> = ({ size, color = C.ink }) => (
  <svg width={size} height={size} viewBox="8 8 48 48"><path d={MarkPath} fill={color} /></svg>
);

/* masked line reveal: text rises out of a slot */
const Rise: React.FC<{ t: number; at: number; out?: number; children: React.ReactNode; style?: React.CSSProperties; dur?: number }> =
  ({ t, at, out = 99, children, style, dur = 0.7 }) => {
    const y = ip(t, at, at + dur, 105, 0) + ip(t, out, out + 0.45, 0, -105, EIO);
    return (
      <div style={{ overflow: "hidden", paddingBottom: "0.12em", marginBottom: "-0.12em" }}>
        <div style={{ transform: `translateY(${y}%)`, ...style }}>{children}</div>
      </div>
    );
  };

const TASKS = ["Reply to the enquiry", "Chase the details", "Update the record", "Send the follow-up"];
const STATION_LAB = ["Read the enquiry", "Ask for the details", "Update the record", "Send the follow-up"];
const STEPS = [
  { at: 5.0, ts: "10:42", txt: "Enquiry read." },
  { at: 5.85, ts: "10:42", txt: "Details requested." },
  { at: 6.85, ts: "10:43", txt: "Record updated." },
  { at: 7.85, ts: "10:43", txt: "Follow-up scheduled." },
  { at: 8.75, ts: "10:44 · 15% discount asked", txt: "Your team decides.", amber: true },
];
const SCENES = [
  [0, 2.9, "01", "The problem"], [2.9, 4.8, "02", "Twinthos"], [4.8, 9.85, "03", "How it works"],
  [9.85, 12.8, "04", "What you get"], [12.8, 15, "05", "The promise"],
] as const;

export const Show15: React.FC = () => {
  const f = useCurrentFrame();
  const { fps, width: W, height: H } = useVideoConfig();
  const t = f / fps;
  const P = H > W; // portrait cut
  const u = Math.min(W, H) / 1080; // unit scale
  const cx = W / 2, cy = P ? H * 0.47 : H / 2;
  const R = 300 * u;
  const pt = (deg: number, r = R) => [cx + r * Math.sin((deg * Math.PI) / 180), cy - r * Math.cos((deg * Math.PI) / 180)];

  /* ── marker angle along the ring ── */
  const ang =
    t < 5.25 ? 0 :
    t < 6.25 ? ip(t, 5.25, 5.85, 0, 90, EIO) :
    t < 7.25 ? ip(t, 6.25, 6.85, 90, 180, EIO) :
    t < 8.25 ? ip(t, 7.25, 7.85, 180, 270, EIO) :
    ip(t, 8.25, 8.75, 270, 315, EIO);
  const arrivals = [5.0, 5.85, 6.85, 7.85];
  const decided = t >= 8.75;

  /* ── scene-level camera ── */
  const push = 1 + 0.035 * ip(t, 0, 15, 0, 1, Easing.linear);
  const s4 = ip(t, 9.75, 10.55, 0, 1, EIO);
  const gScale = 1 - (P ? 0.32 : 0.24) * s4;
  const gdx = P ? 0 : -430 * u * s4, gdy = P ? -300 * u * s4 : 0;
  const gOut = 1 - ip(t, 12.65, 13.15, 0, 1);
  const finalFade = 1 - ip(t, 14.45, 14.98, 0, 1, Easing.linear);

  /* ring geometry */
  const circ = 2 * Math.PI * R;
  const ringDraw = ip(t, 3.15, 4.25, 0, 1, EIO);
  const prog = t < 5.0 ? 0 : ang / 360;
  const ringOn = ip(t, 3.1, 3.3, 0, 1);

  /* light sweep across the ring after it closes */
  const sweep = ip(t, 4.15, 4.95, -0.4, 1.4, Easing.linear);

  const [mx, my] = pt(ang);
  const markerOn = win(t, 4.75, 12.9, 0.3, 0.4);
  const mCol = decided ? C.amber : C.green;
  const branchDraw = ip(t, 8.8, 9.35, 0, 1);
  const [bx0, by0] = pt(315);
  const [bx1, by1] = pt(315, R + 170 * u);

  /* pulses on arrival */
  const pulse = (at: number) => { const k = ip(t, at, at + 0.9, 0, 1, Easing.out(Easing.quad)); return t >= at && k < 1 ? k : -1; };

  /* scatter positions for the opening task pills (relative to centre) */
  const scatter = P
    ? [[-250, -460], [230, -380], [-230, 420], [250, 500]]
    : [[-560, -270], [540, -300], [-600, 255], [560, 285]];
  const stationAng = [0, 90, 180, 270];
  const labOff = (i: number) => {
    const [x, y] = pt(stationAng[i], R + 44 * u);
    return [x, y];
  };

  const chrome = ip(t, 0.15, 0.7, 0, 1) * finalFade;
  const headSize = (P ? 92 : 112) * u;

  return (
    <AbsoluteFill style={{ background: C.bg, fontFamily: C.sans, color: C.ink, overflow: "hidden" }}>
      {/* atmosphere: soft field + vignette */}
      <AbsoluteFill style={{
        background: `radial-gradient(${60 * u}0px ${45 * u}0px at ${cx}px ${cy}px, rgba(108,199,154,${0.07 * win(t, 3.4, 12.9, 1, 0.6)}), transparent 70%)`,
      }} />
      <AbsoluteFill style={{ background: `radial-gradient(120% 90% at 50% 45%, transparent 55%, rgba(0,0,0,.55) 100%)` }} />

      <AbsoluteFill style={{ transform: `scale(${push})`, opacity: finalFade }}>
        {/* ═════ 01 · THE PROBLEM ═════ */}
        {t < 4.4 && TASKS.map((txt, i) => {
          const at = 0.15 + i * 0.22;
          const pop = ip(t, at, at + 0.5, 0, 1, Easing.bezier(0.3, 1.6, 0.4, 1));
          const fly = ip(t, 2.95 + i * 0.05, 3.85 + i * 0.05, 0, 1, EIO);
          const jit = (1 - fly) * Math.min(1, t * 2);
          const jx = Math.sin(t * (7 + i * 1.3) + i) * 5 * u * jit, jy = Math.cos(t * (6 + i) + i * 2) * 4 * u * jit;
          const [sx, sy] = [cx + scatter[i][0] * u, cy + scatter[i][1] * u];
          const [tx, ty] = labOff(i);
          const x = sx + (tx - sx) * fly + jx, y = sy + (ty - sy) * fly + jy;
          const ping = (t - at) % 1.1;
          const align = stationAng[i] === 90 ? "left" : stationAng[i] === 270 ? "right" : "center";
          const ax = align === "left" ? 0 : align === "right" ? -100 : -50;
          const ay = stationAng[i] === 0 ? -100 : stationAng[i] === 180 ? 0 : -50;
          const axx = -50 + (ax + 50) * fly, ayy = -50 + (ay + 50) * fly;
          return (
            <div key={i} style={{
              position: "absolute", left: x, top: y, transform: `translate(${axx}%, ${ayy}%) scale(${pop * (1 - 0.18 * fly)})`,
              opacity: pop * (1 - ip(t, 3.9, 4.3, 0, 1)), display: "flex", alignItems: "center", gap: 12 * u,
              padding: `${14 * u * (1 - fly)}px ${20 * u * (1 - fly)}px`, borderRadius: 999,
              border: `1.5px solid rgba(244,240,230,${0.22 * (1 - fly)})`, background: `rgba(28,31,27,${0.9 * (1 - fly)})`,
              fontFamily: C.mono, fontSize: 24 * u, letterSpacing: "-.01em", color: C.ink2, whiteSpace: "nowrap",
            }}>
              <span style={{ position: "relative", width: 10 * u, height: 10 * u, opacity: 1 - fly }}>
                <span style={{ position: "absolute", inset: 0, borderRadius: 99, background: C.amber }} />
                <span style={{ position: "absolute", inset: 0, borderRadius: 99, border: `2px solid ${C.amber}`, transform: `scale(${1 + ping * 2.2})`, opacity: Math.max(0, 1 - ping * 1.4) }} />
              </span>
              {txt}
            </div>
          );
        })}
        {t < 3.6 && (
          <div style={{ position: "absolute", left: 0, right: 0, top: cy, transform: "translateY(-50%)", textAlign: "center" }}>
            <Rise t={t} at={0.55} out={2.8} style={{ fontFamily: C.mono, fontSize: 20 * u, letterSpacing: ".14em", color: C.amber, marginBottom: 26 * u }}>
              4 SMALL JOBS · ALL WAITING ON SOMEONE
            </Rise>
            <div style={{ fontSize: headSize, fontWeight: 500, letterSpacing: "-.035em", lineHeight: 1.0 }}>
              <Rise t={t} at={0.8} out={2.85}>Your people have</Rise>
              <Rise t={t} at={0.98} out={2.92}><span style={{ color: C.ink2 }}>better work to do.</span></Rise>
            </div>
          </div>
        )}

        {/* ═════ 02–04 · THE WHEEL ═════ */}
        <AbsoluteFill style={{
          transformOrigin: `${cx}px ${cy}px`, transform: `translate(${gdx}px, ${gdy}px) scale(${gScale})`,
          opacity: gOut,
        }}>
          <svg width={W} height={H} style={{ position: "absolute", inset: 0 }}>
            <defs>
              <linearGradient id="sw" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0" stopColor="#fff" stopOpacity="0" /><stop offset=".5" stopColor="#fff" stopOpacity=".9" /><stop offset="1" stopColor="#fff" stopOpacity="0" />
              </linearGradient>
              <mask id="swm"><rect x={cx - R - 60 + sweep * (2 * R + 120) - 90} y={0} width={180} height={H} fill="url(#sw)" transform={`rotate(18 ${cx} ${cy})`} /></mask>
              <filter id="glow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation={10 * u} /></filter>
            </defs>
            {/* base ring, drawn clockwise from 12 o'clock */}
            <circle cx={cx} cy={cy} r={R} fill="none" stroke={C.line} strokeWidth={3 * u}
              strokeDasharray={`${circ * ringDraw} ${circ}`} transform={`rotate(-90 ${cx} ${cy})`} opacity={ringOn} />
            <circle cx={cx} cy={cy} r={R} fill="none" stroke={C.ink} strokeWidth={3 * u} mask="url(#swm)" opacity={0.85 * ringOn} />
            {/* progress arc */}
            <circle cx={cx} cy={cy} r={R} fill="none" stroke={C.green} strokeWidth={5 * u} strokeLinecap="round"
              strokeDasharray={`${circ * prog} ${circ}`} transform={`rotate(-90 ${cx} ${cy})`} opacity={prog > 0 ? 1 : 0} />
            {/* comet trail */}
            {t > 5.2 && t < 8.8 && [0.06, 0.12, 0.2].map((k, i) => (
              <circle key={i} cx={cx} cy={cy} r={R} fill="none" stroke={C.green} strokeWidth={(14 - i * 4) * u} strokeLinecap="round" opacity={0.18 - i * 0.05}
                strokeDasharray={`${circ * Math.min(k, prog)} ${circ}`} transform={`rotate(${-90 + ang - Math.min(k, prog) * 360} ${cx} ${cy})`} filter="url(#glow)" />
            ))}
            {/* stations */}
            {stationAng.map((a, i) => {
              const [x, y] = pt(a);
              const on = t >= arrivals[i];
              const k = pulse(arrivals[i]);
              const appear = ip(t, 3.55 + i * 0.12, 3.95 + i * 0.12, 0, 1, Easing.bezier(0.3, 1.6, 0.4, 1));
              return (
                <g key={i}>
                  {k >= 0 && <circle cx={x} cy={y} r={(14 + 46 * k) * u} fill="none" stroke={C.green} strokeWidth={2 * u} opacity={1 - k} />}
                  <circle cx={x} cy={y} r={11 * u * appear} fill={on ? C.green : C.bg} stroke={on ? C.green : C.ink2} strokeWidth={2.5 * u} />
                </g>
              );
            })}
            {/* decision point + the line where a person decides */}
            {(() => {
              const app = ip(t, 4.0, 4.4, 0, 1);
              const [x, y] = pt(315);
              const [lx0, ly0] = pt(315, R - 26 * u), [lx1, ly1] = pt(315, R + 26 * u);
              const k = pulse(8.75);
              return (
                <g opacity={app}>
                  <line x1={lx0} y1={ly0} x2={lx1} y2={ly1} stroke={decided ? C.amber : C.ink2} strokeWidth={3 * u} strokeLinecap="round" />
                  {k >= 0 && <circle cx={x} cy={y} r={(14 + 60 * k) * u} fill="none" stroke={C.amber} strokeWidth={2 * u} opacity={1 - k} />}
                  <line x1={bx0} y1={by0} x2={bx0 + (bx1 - bx0) * branchDraw} y2={by0 + (by1 - by0) * branchDraw}
                    stroke={C.amber} strokeWidth={4 * u} strokeDasharray={`${10 * u} ${9 * u}`} />
                  <circle cx={bx1} cy={by1} r={26 * u * ip(t, 9.2, 9.55, 0, 1, Easing.bezier(0.3, 1.6, 0.4, 1))} fill={C.bg} stroke={C.amber} strokeWidth={3 * u} />
                  <g transform={`translate(${bx1} ${by1}) scale(${u * ip(t, 9.3, 9.6, 0, 1)})`} fill={C.amber}>
                    <circle cx="0" cy="-6" r="6" /><path d="M-11 13 a11 9 0 0 1 22 0z" />
                  </g>
                </g>
              );
            })()}
            {/* marker: the enquiry */}
            <g opacity={markerOn} transform={`translate(${mx} ${my})`}>
              <circle r={26 * u} fill={mCol} opacity={0.22} filter="url(#glow)" />
              <circle r={15 * u * ip(t, 4.75, 5.1, 0, 1, Easing.bezier(0.3, 1.8, 0.4, 1))} fill={mCol} />
              <circle r={6 * u} fill={C.bg} opacity={ip(t, 4.9, 5.2, 0, 1)} />
            </g>
          </svg>

          {/* station labels (the opening pills land here) */}
          {stationAng.map((a, i) => {
            const [x, y] = labOff(i);
            const on = t >= arrivals[i];
            const vis = ip(t, 3.75, 4.15, 0, 1);
            const align = a === 90 ? "left" : a === 270 ? "right" : "center";
            const tx = align === "left" ? "0%" : align === "right" ? "-100%" : "-50%";
            const ty = a === 0 ? "-100%" : a === 180 ? "0%" : "-50%";
            return (
              <div key={i} style={{
                position: "absolute", left: x, top: y, transform: `translate(${tx}, ${ty})`, opacity: vis,
                fontFamily: C.mono, fontSize: 24 * u * 0.82 / (1), letterSpacing: "-.01em", whiteSpace: "nowrap",
                color: on ? C.ink : C.mute, transition: "none",
              }}>{STATION_LAB[i]}</div>
            );
